'use strict';

// Migrates customers_v1 -> customers_v2 in data/customers.db using migration/dedup-plan.json.
// Usage: node migration/apply.js run

const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

const ROOT = path.resolve(__dirname, '..');
const DB_PATH = path.join(ROOT, 'data', 'customers.db');
const PLAN_PATH = path.join(__dirname, 'dedup-plan.json');

function normalizeEmail(email) {
  return email === null || email === undefined ? null : String(email).trim().toLowerCase();
}

function run() {
  const plan = JSON.parse(fs.readFileSync(PLAN_PATH, 'utf8'));
  const db = new DatabaseSync(DB_PATH);

  try {
    const v1Rows = db
      .prepare('SELECT id, full_name, email, phone, city, updated_at FROM customers_v1')
      .all();
    const byId = new Map(v1Rows.map((r) => [r.id, r]));

    // Check that the plan covers every v1 row exactly once and that each group is consistent.
    const seen = new Set();
    for (const g of plan.groups) {
      const ids = [g.keep, ...g.drop];
      for (const id of ids) {
        const row = byId.get(id);
        if (!row) throw new Error(`plan references unknown id ${id}`);
        if (seen.has(id)) throw new Error(`id ${id} appears more than once in plan`);
        seen.add(id);
        if (normalizeEmail(row.email) !== g.email) {
          throw new Error(`id ${id} email does not match group ${g.email}`);
        }
      }
    }
    if (seen.size !== v1Rows.length) {
      throw new Error(`plan covers ${seen.size} rows but customers_v1 has ${v1Rows.length}`);
    }

    db.exec('BEGIN');
    db.exec('DROP TABLE IF EXISTS customers_v2');
    db.exec(`CREATE TABLE customers_v2 (
      customer_id INTEGER PRIMARY KEY,
      full_name TEXT,
      email TEXT,
      phone TEXT,
      city TEXT,
      last_contact TEXT
    )`);

    const insert = db.prepare(
      'INSERT INTO customers_v2 (customer_id, full_name, email, phone, city, last_contact) VALUES (?, ?, ?, ?, ?, ?)'
    );

    let inserted = 0;
    for (const g of plan.groups) {
      const row = byId.get(g.keep);
      insert.run(
        row.id,
        row.full_name,
        normalizeEmail(row.email),
        row.phone,
        row.city,
        row.updated_at
      );
      inserted++;
    }
    db.exec('COMMIT');

    const count = db.prepare('SELECT COUNT(*) AS n FROM customers_v2').get().n;
    const dropped = seen.size - inserted;
    console.log(
      JSON.stringify({ source_rows: v1Rows.length, groups: plan.groups.length, inserted, dropped, customers_v2_rows: count })
    );
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch (_) {
      // no open transaction
    }
    throw err;
  } finally {
    db.close();
  }
}

function main() {
  const cmd = process.argv[2];
  if (cmd !== 'run') {
    console.error('Usage: node migration/apply.js run');
    process.exit(1);
  }
  run();
}

main();

